package com.github.lucasoliveira.platform.product.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false,unique=true) String sku; @Column(nullable=false) String name; String description; @Column(nullable=false,precision=15,scale=2) BigDecimal price; @Column(nullable=false) Integer stock; @Column(nullable=false) Boolean active=true; @Column(name="created_at",nullable=false) OffsetDateTime createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public String getSku(){return sku;} public void setSku(String v){sku=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public Integer getStock(){return stock;} public void setStock(Integer v){stock=v;} public Boolean getActive(){return active;} public void setActive(Boolean v){active=v;} public OffsetDateTime getCreatedAt(){return createdAt;}}
